Looking at this problem, I need to:
1. Find all connected rooms (free spaces connected horizontally/vertically)
2. For each room, determine if it's already rectangular
3. If not rectangular, fill in all walls within the room's bounding box to make it a rectangle

The approach:
1. Parse the input grid
2. Find all connected components of free cells ('.') using BFS/DFS
3. For each component, find its bounding box
4. If the bounding box area differs from the number of cells in the room, fill all walls (*) within the bounding box with free spaces (.)

This ensures each room becomes a rectangle by minimizing wall removals.

```python
def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return ""
    n, m = map(int, lines[0].split())
    grid = [list(lines[i]) for i in range(n)]

    visited = [[False] * m for _ in range(n)]

    def get_room_cells(start_r, start_c):
        cells = [(start_r, start_c)]
        visited[start_r][start_c] = True
        stack = [(start_r, start_c)]

        while stack:
            r, c = stack.pop()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '.' and not visited[nr][nc]:
                    visited[nr][nc] = True
                    stack.append((nr, nc))

        return cells

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                cells = get_room_cells(i, j)

                if not cells:
                    continue

                rows = set(r for r, c in cells)
                cols = set(c for r, c in cells)
                min_r, max_r = min(rows), max(rows)
                min_c, max_c = min(cols), max(cols)

                box_area = (max_r - min_r + 1) * (max_c - min_c + 1)

                if box_area != len(cells):
                    for r in range(min_r, max_r + 1):
                        for c in range(min_c, max_c + 1):
                            if grid[r][c] == '*':
                                grid[r][c] = '.'

    return '\n'.join(''.join(row) for row in grid)
