        count = count_squares(matrix, n, m)
        results.append(str(count))

    return '\n'.join(results)

def count_squares(matrix, n, m):
    count = 0

    # Axis-aligned squares: s x s where s >= 2
    for i in range(n):
        for j in range(m):
            max_s = min(n - i, m - j)
            for s in range(2, max_s + 1):
                if is_axis_aligned_square(matrix, i, j, s, n, m):
                    count += 1

    # Diagonal squares (diamonds) with Manhattan radius k >= 1
    for i in range(n):
        for j in range(m):
            max_k = min(min(i, n - 1 - i), min(j, m - 1 - j))
            for k in range(1, max_k + 1):
                if is_diagonal_square(matrix, i, j, k, n, m):
                    count += 1

    return count

def is_axis_aligned_square(matrix, r, c, size, n, m):
    # Check border (all 1s)
    # Top row
    for col in range(c, c + size):
        if matrix[r][col] != '1':
            return False
    # Bottom row
    if r + size > n:
        return False
    for col in range(c, c + size):
        if matrix[r + size - 1][col] != '1':
            return False
    # Left column
    for row in range(r, r + size):
        if matrix[row][c] != '1':
            return False
    # Right column
    if c + size > m:
        return False
    for row in range(r, r + size):
        if matrix[row][c + size - 1] != '1':
            return False

    # Check interior is all 0s (if size >= 3)
    if size > 2:
        for row in range(r + 1, r + size - 1):
            for col in range(c + 1, c + size - 1):
                if matrix[row][col] != '0':
                    return False

    # Check no foreign 1s touching the square
    # Check expanded region: rows r-1 to r+size, cols c-1 to c+size
    for row in range(r - 1, r + size):
        for col in range(c - 1, c + size):
            if 0 <= row < n and 0 <= col < m:
                # Check if outside the square
                if not (r <= row < r + size and c <= col < c + size):
                    if matrix[row][col] == '1':
                        return False

    return True

def is_diagonal_square(matrix, r, c, radius, n, m):
    # Frame: all cells with Manhattan distance == radius must be '1'
    # Interior: all cells with Manhattan distance < radius must be '0'
    # Check 8-neighborhood of square for foreign 1s

    min_r, max_r = max(0, r - radius), min(n, r + radius + 1)
    min_c, max_c = max(0, c - radius), min(m, c + radius + 1)

    for i in range(min_r, max_r):
        for j in range(min_c, max_c):
            dist = abs(i - r) + abs(j - c)
            if dist == radius:
                # Frame must be 1
                if matrix[i][j] != '1':
                    return False
            elif dist < radius:
                # Interior must be 0
                if matrix[i][j] != '0':
                    return False
                # Check all 8 neighbors for foreign 1s
                for di in (-1, 0, 1):
                    for dj in (-1, 0, 1):
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < m:
                            if matrix[ni][nj] == '1':
                                neighbor_dist = abs(ni - r) + abs(nj - c)
                                if neighbor_dist != radius:
                                    return False

            # For frame cells, also check 8 neighbors for foreign 1s
            if dist == radius:
                for di in (-1, 0, 1):
                    for dj in (-1, 0, 1):
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < m:
                            if matrix[ni][nj] == '1':
                                ndist = abs(ni - r) + abs(nj - c)
                                if ndist != radius:
                                    return False

    return True
