    n = int(data[0])
    w = int(data[1])
    v = int(data[2])
    u = int(data[3])

    polygon = []
    idx = 4
    for _ in range(n):
        polygon.append((int(data[idx]), int(data[idx+1])))
        idx += 2

    if not polygon:
        return f"{w/u:.10f}"

    leftmost = min(p[0] for p in polygon)
    rightmost = max(p[0] for p in polygon)

    if leftmost >= 0:
        return f"{w/u:.10f}"

    # Find vertices that have y in [0, w]
    critical_points = [(x, y) for x, y in polygon if 0 <= y <= w]

    if not critical_points:
        return f"{w/u:.10f}"

    # For each critical y-coordinate, find the leftmost x
    y_vals = sorted(set(p[1] for p in critical_points))

    # Use computational geometry: for each edge segment, find when x=0
    crossing_times = []

    for i in range(len(polygon)):
        x1, y1 = polygon[i]
        x2, y2 = polygon[(i + 1) % len(polygon)]

        # Edge is horizontal
        if y1 == y2 and y1 >= 0 and y1 <= w:
            if x1 < 0 and x2 >= 0 or x2 < 0 and x1 >= 0:
                crossing_times.append(0.0)
            continue

        # Non-horizontal edge - find if it crosses x=0 and if y is in [0, w]
        # Left edge of polygon blocks at time when x=0 at some y

        if y1 != y2:
            # Find y range covered by this edge
            y_low = min(y1, y2)
            y_high = max(y1, y2)

            if y_high > w or y_low < 0:
                continue

            # Find the t where x=0 along this edge
            if (x1 * x2) < 0 or (x1 == 0 or x2 == 0):
                # Edge crosses or touches x=0
                # Parameter t along edge
                param = -x1 / (x2 - x1) if x1 != x2 else 0
                y_cross = y1 + param * (y2 - y1)

                if 0 <= y_cross <= w:
                    t_cross = param if (x2 - x1) > 0 else 0
                    # t where vertex reaches x=0
                    t_cross = abs(x1) / v
                    crossing_times.append(t_cross)

    # Compute blocking constraints
    constraints = []

    for y in y_vals:
        x_min, x_max = float('inf'), float('-inf')

        for edge in polygon:
            continue

        # Use vertex-based approach
        for x, y_v in critical_points:
            if abs(y - y_v) < 1e-9:
                x_min = min(x_min, x)
                x_max = max(x_max, x)

        if x_min < 0:
            t_block = -x_min / v
            if y <= u * t_block:
                constraints.append(t_block)

    ans = w / u

    if constraints:
        max_constraint = max(constraints)
        ans = max(ans, max_constraint + w / u)

    return f"{ans:.10f}"
