            if grid[r][c] == 'F':
                finish = (r, c)
                break

    def get_moves(lr, ud):
        base = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}
        res = {}
        for mv, (dr, dc) in base.items():
            if mv in ('L', 'R') and lr:
                res[mv] = (dc, dr if mv == 'L' else -dr) if mv == 'L' else (0, 0)
                res[mv] = (0, 1) if mv == 'L' else (0, -1)
            else:
                res[mv] = (dr, dc)
            if mv in ('U', 'D') and ud:
                res[mv] = (-dr, dc) if mv == 'U' else (dr, dc)
                res[mv] = (1, 0) if mv == 'U' else (-1, 0)
        return res

    def bfs(start, mapping):
        vis = set()
        q = deque([(start, "")])
        vis.add(start)
        while q:
            (r, c), path = q.popleft()
            if (r, c) == finish:
                return path
            for mv in ["U", "D", "L", "R"]:
                dr, dc = mapping[mv]
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if (nr, nc) not in vis and grid[nr][nc] != '*':
                        vis.add((nr, nc))
                        q.append(((nr, nc), path + mv))
        return None

    mapping = get_moves(swap_LR, swap_UD)
    result = bfs((0, 0), mapping)
    if result:
        return result + "\n"
    return ""

