    lines = input_str.strip().split('\n')

    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    p = list(map(int, lines[2].split()))
    m = int(lines[3])
    b = list(map(int, lines[4].split()))

    # Check if all elements of b can be found in a in correct relative order
    from collections import defaultdict

    positions = defaultdict(list)
    for i in range(n):
        positions[a[i]].append(i)

    INF = float('inf')

    # Build the DP: dp[j][pos] = minimum cost matching b[j] at position pos
    # Optimized space: prev_dp position -> cost

    # Precompute prefix sums of p for quick range cost calculation
    prefix_p = [0] * (n + 1)
    for i in range(n):
        prefix_p[i+1] = prefix_p[i] + p[i]

    # Helper to compute cost between two positions
    def cost_between(prev_pos, curr_pos, limit):
        """Cost for elements between prev_pos and curr_pos where limit is prev_target value"""
        total = 0
        for k in range(prev_pos + 1, curr_pos):
            if a[k] > limit:
                total += p[k]  # Must delete
            else:
                total += min(0, p[k])  # Can keep (cost 0) or delete (cost p[k])
        return total

    def post_cost(pos, limit):
        """Cost for elements after pos where limit is last target value"""
        total = 0
        for k in range(pos + 1, n):
            if a[k] > limit:
                total += p[k]  # Must delete (becomes new record)
            else:
                total += min(0, p[k])  # Can keep
        return total

    # Initialize DP for j=0: b[0] at various positions
    first = b[0]
    first_positions = positions.get(first, [])

    if not first_positions:
        return "NO\n"

    # For j=0, must delete all elements before the chosen position
    curr_dp = {}
    for pos in first_positions:
        curr_dp[pos] = prefix_p[pos]  # Cost = delete all before

    # Process j from 1 to m-1
    for j in range(1, m):
        target = b[j]
        prev_target = b[j-1]

        prev_positions = positions.get(prev_target, [])
        curr_positions = positions.get(target, [])

        if not prev_positions or not curr_positions:
            break

        new_dp = {}
        for curr in curr_positions:
            min_total = INF
            for prev in prev_positions:
                if prev >= curr:
                    break

                transition = cost_between(prev, curr, prev_target)
                total = curr_dp[prev] + transition

                if total < min_total:
                    min_total = total

            if min_total != INF:
                new_dp[curr] = min_total

        curr_dp = new_dp
        if not curr_dp:
            break

    if not curr_dp:
        return "NO\n"

    # Add post-processing cost for each valid last position
    finals = []
    last_target = b[m-1]

    for pos, cost in curr_dp.items():
        add_cost = post_cost(pos, last_target)
        finals.append(cost + add_cost)

    if not finals:
        return "NO\n"

    min_cost = min(finals)
    return f"YES\n{min_cost}"
