Looking at this problem, I need to determine if a car can return to its starting intersection with an odometer showing 0. The key insight is:

1. Find which strongly connected components (SCCs) exist in the graph
2. For each SCC, compute the GCD of all cycle lengths (this is the fundamental cycle structure)
3. For each query (v, s, t), check if (t - s) is divisible by the GCD of the SCC containing v

Let me implement a clean solution:

```python
import math
from collections import defaultdict

def solution(input_str):
    try:
        import os
        lines = input_str.strip().split('\n')
        if not lines:
            return ''

        n, m = map(int, lines[0].split())

        adj = defaultdict(list)
        for i in range(1, m + 1):
            a, b, l = map(int, lines[i].split())
            adj[a].append((b, l))

        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a

        visited = [False] * (n + 1)
        low = [0] * (n + 1)
        ids = [-1] * (n + 1)
        on_stack = [False] * (n + 1)
        stack = []
        id_counter = [0]
        scc_gcds = []
        node_to_scc = [-1] * (n + 1)

        sys.setrecursionlimit(300000)

        def tarjan_dfs(u):
            nonlocal id_counter
            stack.append(u)
            on_stack[u] = True
            ids[u] = low[u] = id_counter[0]
            id_counter[0] += 1

            for v, w in adj[u]:
                if ids[v] == -1:
                    tarjan_dfs(v)
                    low[u] = min(low[u], low[v])
                elif on_stack[v]:
                    low[u] = min(low[u], ids[v])

            if ids[u] == low[u]:
                # Found an SCC
                scc_nodes = []
                while stack:
                    node = stack.pop()
                    on_stack[node] = False
                    node_to_scc[node] = len(scc_gcds)
                    scc_nodes.append(node)
                    if node == u:
                        break

                # Compute GCD of cycle lengths in this SCC
                if len(scc_nodes) <= 1:
                    scc_gcds.append(0)
                else:
                    all_edge_weights = set()
                    for u in scc_nodes:
                        for v, w in adj[u]:
                            if v in scc_nodes:
                                all_edge_weights.add(w)

                    if all_edge_weights:
                        scc_gcds.append(math.gcd(*all_edge_weights))
                    else:
                        scc_gcds.append(0)

        for i in range(1, n + 1):
            if ids[i] == -1:
                tarjan_dfs(i)

        q = int(lines[m + 1])
        results = []

        for i in range(m + 2, m + 2 + q):
            v, s, t = map(int, lines[i].split())

            if s == 0:
                results.append("YES")
            else:
                scc_idx = node_to_scc[v]
                g = scc_gcds[scc_idx]

                # For odometer to show 0, total_distance ≡ -s (mod t)
                # Total distance must be a multiple of g
                # So we need (-s mod t) to be divisible by g
                if g == 0:
                    # If g == 0, only distance 0 is achievable
                    # Only works if s == 0, which we already handled
                    results.append("NO")
                else:
                    remainder = (-s) % t
                    if remainder % g == 0:
                        results.append("YES")
                    else:
                        results.append("NO")

        return '\n'.join(results) + '\n'
    except Exception:
        return ''

if __name__ == "__main__":
    test_input = "4 5\n1 2 1\n2 3 1\n3 1 2\n1 4 1\n4 3 2\n2\n1 2 4\n4 3 5\n"
    print(solution(test_input))
