1. Try match outcomes in order of preference for Team A (3:0 > 3:1 > 3:2 > 2:3 > 1:3 > 0:3)
2. Construct valid set scores following volleyball rules
3. Ensure total points match the input

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    m = int(lines[0])
    results = []

    for i in range(1, m + 1):
        if i >= len(lines):
            break

        parts = lines[i].split()
        if len(parts) < 2:
            results.append("Impossible")
            continue

        try:
            a, b = int(parts[0]), int(parts[1])
        except:
            results.append("Impossible")
            continue

        best = find_best_outcome(a, b)
        if best:
            da, db, sets = best
            results.append(f"{da}:{db}")
            results.append(" ".join([f"{s[0]}:{s[1]}" for s in sets]) + " ")
        else:
            results.append("Impossible")

    return '\n'.join(results)

def find_best_outcome(a, b):
    # Try outcomes in preference order for Team A
    for da, db in [(3,0), (3,1), (3,2), (2,3), (1,3), (0,3)]:
        result = construct_sets(a, b, da, db)
        if result and valid_sets(result, a, b):
            return da, db, result
    return None

def construct_sets(a, b, da, db):
    total = da + db
    if total < 1 or total > 5:
        return None

    # Build sets: Team A wins da sets, opponent wins db sets
    # Winning scores: 25-0 to 25-24 for first 4 sets, 15-0 to 15-14 for 5th set
    sets = []

    for i in range(total):
        a_wins = i < da
        # Greedy: A wins go near start to use points
        if a_wins:
            p_a = min(25, a)
            p_b = min(24, b)
            sets.append((p_a, p_b))
        else:
            p_a = min(24, a)
            p_b = max(15, b)
            sets.append((p_a, p_b))

    return sets

def valid_sets(sets, a, b):
    a_total = sum(s[0] for s in sets)
    b_total = sum(s[1] for s in sets)
    return a_total == a and b_total == b
