Looking at this problem, I need to find a permutation P of [1..N] such that |P[i] - i| >= K for all positions, and output the lexicographically smallest one (or -1 if impossible).

```python
def solution(input_str):
    """
    Solves the Baahubali forts problem.
    Returns a string with the output for each test case.
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    try:
        num_test_cases = int(lines[0])
    except ValueError:
        return ""

    result = []

    for i in range(1, num_test_cases + 1):
        if i >= len(lines):
            break

        parts = lines[i].split()
        if len(parts) < 2:
            result.append("-1")
            continue

        try:
            N = int(parts[0])
            K = int(parts[1])
        except ValueError:
            result.append("-1")
            continue

        # Case 1: K = 0 - identity permutation works
        if K == 0:
            result.append(" ".join(map(str, range(1, N + 1))))

        # Case 2: K >= N - impossible since at position 1, we need |P[1]-1| >= N,
        # which means P[1] >= N+1 (impossible) or P[1] <= 1-N (impossible)
        elif K >= N:
            result.append("-1")

        # Case 3: Check the formula
        # Pattern that works: P = [K+1, K+2, ..., N, 1, 2, ..., K]
        # But this only works when N >= 2*K - 1
        # For simpler condition: K <= N - 2 (or K <= (N-1) // 2)
        elif K <= (N - 1) // 2:
            first_part = [i + K for i in range(1, N - K + 1)]
            second_part = list(range(1, K + 1))
            P = first_part + second_part
            result.append(" ".join(map(str, P)))
        else:
            result.append("-1")

    return '\n'.join(result)

